fn find_max(nums: Vec<i32>) -> i32 {
    // Since the vector is guaranteed to be non-empty, we can safely take the first element
    let mut iter = nums.into_iter();
    let mut max_val = iter.next().unwrap();

    // Iterate through the rest and update max_val when we find a larger element
    for x in iter {
        if x > max_val {
            max_val = x;
        }
    }

    max_val
}

